import ipaddress, urllib.parse, socket

ALLOWED_HOSTS = {"api.trusted-partner.com", "cdn.example.com"}

def is_safe_url(url: str) -> bool:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return False  # Block file://, gopher://, dict://, etc.
    host = parsed.hostname
    if host not in ALLOWED_HOSTS:
        return False  # Allowlist-only policy
    return True

BLOCKED_NETWORKS = [
    ipaddress.ip_network("10.0.0.0/8"),
    ipaddress.ip_network("172.16.0.0/12"),
    ipaddress.ip_network("192.168.0.0/16"),
    ipaddress.ip_network("169.254.0.0/16"),  # link-local / IMDS
    ipaddress.ip_network("127.0.0.0/8"),      # loopback
    ipaddress.ip_network("::1/128"),           # IPv6 loopback
    ipaddress.ip_network("fd00::/8"),          # IPv6 ULA
]

def resolve_and_check(hostname: str) -> bool:
    try:
        addr = socket.getaddrinfo(hostname, None)[0][4][0]
        ip = ipaddress.ip_address(addr)
        for network in BLOCKED_NETWORKS:
            if ip in network:
                return False  # Blocked
        return True
    except Exception:
        return False

