# SECURE — check role at the function level
@app.delete("/api/v1/admin/users/{user_id}")
def delete_user(user_id: int, user=Depends(require_role("admin"))):
    db.delete(User, user_id)
    return {"status": "deleted"}

# Separate read schemas by role
class UserPublicResponse(BaseModel):   # returned to the user themselves
    id: int
    email: str
    display_name: str
    # NOT included: is_admin, stripe_customer_id, internal_notes

class UserAdminResponse(UserPublicResponse):  # returned to admins only
    is_admin: bool
    internal_notes: str
    stripe_customer_id: str

@app.get("/users/{user_id}")
def get_user(user_id: int, caller=Depends(get_current_user)):
    user = db.get(User, user_id)
    if caller.is_admin:
        return UserAdminResponse.from_orm(user)
    return UserPublicResponse.from_orm(user)

